package apps

import (
	"bufio"
	"encoding/json"
	"errors"
	"fmt"
	"io/fs"
	"net/url"
	"path"
	"strings"
	"time"

	"github.com/alexandreh2ag/lacis/common/snapshot"
	"github.com/spf13/afero"
	"go.yaml.in/yaml/v3"
)

// Version files generated by the CI at the app root, by priority.
const (
	DeployInfoJSON = ".app.lacis.json"
	DeployInfoYAML = ".app.lacis.yaml"
	DeployInfoYML  = ".app.lacis.yml"
)

var deployInfoFiles = []string{DeployInfoJSON, DeployInfoYAML, DeployInfoYML}

// deployInfo is the content of a version file; every field is optional but
// version and commit. The version is the tag deployed or, for an env that
// deploys a branch, the branch.
type deployInfo struct {
	Project     string     `json:"project" yaml:"project"`
	App         string     `json:"app" yaml:"app"`
	Env         string     `json:"env" yaml:"env"`
	Version     string     `json:"version" yaml:"version"`
	Commit      string     `json:"commit" yaml:"commit"`
	Branch      string     `json:"branch" yaml:"branch"`
	Tag         string     `json:"tag" yaml:"tag"`
	Repository  string     `json:"repository" yaml:"repository"`
	PipelineID  string     `json:"pipeline_id" yaml:"pipeline_id"`
	PipelineURL string     `json:"pipeline_url" yaml:"pipeline_url"`
	DeployedAt  *time.Time `json:"deployed_at" yaml:"deployed_at"`
	DeployedBy  string     `json:"deployed_by" yaml:"deployed_by"`
}

// readDeployInfo reads the version file of an app, nil when there is none.
// With several files, the first of deployInfoFiles wins and a warning is
// returned.
func readDeployInfo(fsys afero.Fs, root string) (*deployInfo, []error) {
	var found []string
	for _, name := range deployInfoFiles {
		if _, err := fsys.Stat(path.Join(root, name)); err == nil {
			found = append(found, name)
		}
	}
	if len(found) == 0 {
		return nil, nil
	}
	var warnings []error
	if len(found) > 1 {
		warnings = append(warnings, fmt.Errorf("%s: several version files (%s), %s used", root, strings.Join(found, ", "), found[0]))
	}
	file := path.Join(root, found[0])
	b, err := afero.ReadFile(fsys, file)
	if err != nil {
		return nil, append(warnings, err)
	}
	info := &deployInfo{}
	if found[0] == DeployInfoJSON {
		err = json.Unmarshal(b, info)
	} else {
		err = yaml.Unmarshal(b, info)
	}
	if err != nil {
		return nil, append(warnings, fmt.Errorf("%s: %w", file, err))
	}
	if info.Version == "" || info.Commit == "" {
		warnings = append(warnings, fmt.Errorf("%s: version file without version or commit", root))
	}
	info.Repository = stripCredentials(info.Repository)
	return info, warnings
}

func (i *deployInfo) code() *snapshot.Code {
	return &snapshot.Code{
		Source:      snapshot.CodeSourceDeployInfo,
		Version:     i.Version,
		Commit:      i.Commit,
		Branch:      i.Branch,
		Tag:         i.Tag,
		Repository:  i.Repository,
		PipelineID:  i.PipelineID,
		PipelineURL: i.PipelineURL,
		DeployedAt:  i.DeployedAt,
		DeployedBy:  i.DeployedBy,
	}
}

// code is the code of an app read from its .git directory. The version is
// the tag of the commit or, without tag, the branch: an env such as staging
// deploys its branch rather than a tag.
func (r *gitRepo) code() *snapshot.Code {
	version := r.tag
	if version == "" {
		version = r.branch
	}
	return &snapshot.Code{Source: snapshot.CodeSourceGit, Version: version, Commit: r.commit, Branch: r.branch, Tag: r.tag, Repository: r.remote}
}

// gitRepo is what is read of a .git directory, without the git binary.
type gitRepo struct {
	commit string
	branch string
	tag    string
	remote string
}

// readGit reads HEAD, the refs and the origin remote of the repository of
// root; nil without .git. A .git file ("gitdir: …") points to the real
// directory, as for worktrees and submodules.
func readGit(fsys afero.Fs, root string) (*gitRepo, error) {
	dir := path.Join(root, ".git")
	info, err := fsys.Stat(dir)
	if errors.Is(err, fs.ErrNotExist) {
		return nil, nil
	}
	if err != nil {
		return nil, err
	}
	if !info.IsDir() {
		b, err := afero.ReadFile(fsys, dir)
		if err != nil {
			return nil, err
		}
		target, ok := strings.CutPrefix(strings.TrimSpace(string(b)), "gitdir: ")
		if !ok {
			return nil, fmt.Errorf("%s: not a gitdir file", dir)
		}
		if !path.IsAbs(target) {
			target = path.Join(root, target)
		}
		dir = target
	}

	head, err := afero.ReadFile(fsys, path.Join(dir, "HEAD"))
	if err != nil {
		return nil, fmt.Errorf("read %s: %w", path.Join(dir, "HEAD"), err)
	}
	refs := readPackedRefs(fsys, dir)
	repo := &gitRepo{}
	ref, symbolic := strings.CutPrefix(strings.TrimSpace(string(head)), "ref: ")
	if symbolic {
		repo.branch = strings.TrimPrefix(ref, "refs/heads/")
		repo.commit = resolveRef(fsys, dir, ref, refs)
	} else {
		repo.commit = ref // detached HEAD
	}
	if repo.commit != "" {
		repo.tag = tagOf(fsys, dir, repo.commit, refs)
	}
	repo.remote = stripCredentials(originURL(fsys, dir))
	return repo, nil
}

// readPackedRefs maps the refs of packed-refs to their commit; a tag line
// is followed by "^<commit>" when annotated, which the tag then points to.
func readPackedRefs(fsys afero.Fs, dir string) map[string]string {
	refs := map[string]string{}
	f, err := fsys.Open(path.Join(dir, "packed-refs"))
	if err != nil {
		return refs
	}
	defer func() { _ = f.Close() }()
	var last string
	scanner := bufio.NewScanner(f)
	for scanner.Scan() {
		line := scanner.Text()
		switch {
		case strings.HasPrefix(line, "#"):
		case strings.HasPrefix(line, "^"):
			if last != "" {
				refs[last] = strings.TrimPrefix(line, "^")
			}
		default:
			if hash, name, ok := strings.Cut(line, " "); ok {
				refs[name], last = hash, name
			}
		}
	}
	return refs
}

func resolveRef(fsys afero.Fs, dir, ref string, packed map[string]string) string {
	if b, err := afero.ReadFile(fsys, path.Join(dir, ref)); err == nil {
		return strings.TrimSpace(string(b))
	}
	return packed[ref]
}

// tagOf returns a tag pointing to commit, loose tags first, then packed
// ones; annotated tags are only found once packed.
func tagOf(fsys afero.Fs, dir, commit string, packed map[string]string) string {
	if entries, err := afero.ReadDir(fsys, path.Join(dir, "refs", "tags")); err == nil {
		for _, e := range entries {
			if resolveRef(fsys, dir, "refs/tags/"+e.Name(), nil) == commit {
				return e.Name()
			}
		}
	}
	var found string
	for name, hash := range packed {
		if tag, ok := strings.CutPrefix(name, "refs/tags/"); ok && hash == commit && (found == "" || tag < found) {
			found = tag
		}
	}
	return found
}

// originURL reads the URL of the origin remote in .git/config.
func originURL(fsys afero.Fs, dir string) string {
	f, err := fsys.Open(path.Join(dir, "config"))
	if err != nil {
		return ""
	}
	defer func() { _ = f.Close() }()
	inOrigin := false
	scanner := bufio.NewScanner(f)
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if strings.HasPrefix(line, "[") {
			inOrigin = line == `[remote "origin"]`
			continue
		}
		if key, value, ok := strings.Cut(line, "="); ok && inOrigin && strings.TrimSpace(key) == "url" {
			return strings.TrimSpace(value)
		}
	}
	return ""
}

// stripCredentials removes the user and password of an URL: a deploy token
// is often written in the remote.
func stripCredentials(raw string) string {
	u, err := url.Parse(raw)
	if err != nil || u.User == nil || u.Scheme == "" {
		return raw // scp-like git@host:path has no password
	}
	u.User = nil
	return u.String()
}

// repoName is the last element of a repository URL, without ".git":
// git@gitlab.example.com:client/api.git → api.
func repoName(remote string) string {
	remote = strings.TrimSuffix(strings.TrimRight(remote, "/"), ".git")
	if i := strings.LastIndexAny(remote, "/:"); i >= 0 {
		return remote[i+1:]
	}
	return remote
}
